/// A `/video` option (also a key of `/q/video`), by canonical name: short name, aliases and argument enums.
public enum VideoOption: String, CaseIterable, Sendable, Hashable {
    /// Audio bit rate (8k..512k; ignored by flac and wav).
    case audioBitrate = "audio_bitrate"
    /// Downmix to mono or stereo.
    case audioChannels = "audio_channels"
    /// Audio codec (must suit the container).
    case audioCodec = "audio_codec"
    /// Colour of the bars of extend.
    case background = "background"
    /// Skip the result cache (XI_CACHE_ALLOW_BYPASS).
    case bypassCache = "bypass_cache"
    /// Tags for the Cache-Tag response header.
    case cacheTags = "cache_tags"
    /// Changes the URL, the cache key and the ETag.
    case cachebuster = "cachebuster"
    /// Constant rate factor (wins over quality).
    case crf = "crf"
    /// Crop a rectangle (pixels) of the rotated frame before the resize.
    case crop = "crop"
    /// Length of the output from start (exclusive with end).
    case duration = "duration"
    /// End the output at this time of the source (exclusive with duration).
    case end = "end"
    /// Let fit enlarge a smaller source.
    case enlarge = "enlarge"
    /// URL expiry (404 afterwards).
    case expires = "expires"
    /// Pad a fit to the whole box with the background colour.
    case extend = "extend"
    /// Fade in from black and silence, and out to them (seconds).
    case fade = "fade"
    /// Content-Disposition file name.
    case filename = "filename"
    /// Mirror after the rotation.
    case flip = "flip"
    /// Output container (the source extension sets it too); png and webp are waveform pictures, m3u8 and mpd streams (WP-126).
    case format = "format"
    /// Output frame rate (capped by XI_VIDEO_TRANSFORM_MAX_FPS).
    case fps = "fps"
    /// Anchor of fill crops, pads and crops (a compass point; the pixel offsets move crops).
    case gravity = "gravity"
    /// Check the source bytes against a digest.
    case hashsum = "hashsum"
    /// Output height (rounded down to even).
    case height = "height"
    /// Time between keyframes (GOP length, 0.1..60 s).
    case keyframeInterval = "keyframe_interval"
    /// EBU R128 loudness normalisation (single-pass loudnorm).
    case loudnorm = "loudnorm"
    /// Drop the audio stream.
    case mute = "mute"
    /// Fade the watermark overlay in and out (seconds, within its window).
    case overlayFade = "overlay_fade"
    /// Show the watermark overlay (wm, wmu, wmt) from start to end seconds of the output.
    case overlayWindow = "overlay_window"
    /// Expand video presets (XI_VIDEO_TRANSFORM_PRESETS) in place.
    case preset = "preset"
    /// Video quality, mapped onto the codec's CRF scale.
    case quality = "quality"
    /// Stream the source without processing.
    case raw = "raw"
    /// Resize like imgproxy: fit (scale-down, or contain with enlarge; extend pads), fill and fill-down (cover, cropped by gravity), force (stretch).
    case resize = "resize"
    /// Resizing type (auto is not available for video).
    case resizingType = "resizing_type"
    /// Download instead of inline display.
    case returnAttachment = "return_attachment"
    /// Rotate clockwise after the display matrix.
    case rotate = "rotate"
    /// Output sample rate (the codec must support it: Opus 8/12/16/24/48 kHz).
    case sampleRate = "sample_rate"
    /// Length of a stream's segments (1..30 s).
    case segmentDuration = "segment_duration"
    /// Container of a stream's segments: fmp4 (CMAF, HLS 7 and DASH) or ts (MPEG-TS for older HLS players: HLS only, H.264 and AAC muxed in each segment; images with libx264 only).
    case segmentFormat = "segment_format"
    /// Resize without the type.
    case size = "size"
    /// Start the output at this time of the source (exact, from the keyframe before it).
    case start = "start"
    /// Deliver an HLS or DASH stream (as the m3u8 or mpd extension does) with these renditions (at most 8; none: the configured ladder). Rungs above the source are dropped.
    case stream = "stream"
    /// Draw the output's running time (FFmpeg drawtext with a fixed expansion).
    case timecode = "timecode"
    /// Cap the video bit rate (50k..200M).
    case videoBitrate = "video_bitrate"
    /// Video codec (h264 and hevc need the gpl image).
    case videoCodec = "video_codec"
    /// Change the audio level (-60 dB..+20 dB).
    case volume = "volume"
    /// Draw the watermark.
    case watermark = "watermark"
    /// Watermark rotation, clockwise.
    case watermarkRotate = "watermark_rotate"
    /// Watermark shadow: its alpha blurred with sigma, in black.
    case watermarkShadow = "watermark_shadow"
    /// Watermark size in pixels (fit, enlarging; used when the wm scale is 0).
    case watermarkSize = "watermark_size"
    /// Text watermark (replaces watermark_url); markup is sanitised to a whitelist, font `sans 16` by default.
    case watermarkText = "watermark_text"
    /// Watermark image source, fetched like a source (allowlist, SSRF policy, byte limit, origin cache).
    case watermarkUrl = "watermark_url"
    /// Render the audio as a width × height (default 1024×256) PNG or WebP picture.
    case waveform = "waveform"
    /// Output width (rounded down to even).
    case width = "width"

